    function run(uint setMin, address logAddr, uint setMin2) public payable {
        require(true);

        c.Initialized(); if (__ESBMC_reverted()) return;

        bool revertedMin;
        c.SetMinSum(setMin2); bool __rev0 = __ESBMC_reverted(); if (__rev0) { revertedMin = true; } else { revertedMin = false; }

        bool revertedLog;
        c.SetLogFile(logAddr); bool __rev1 = __ESBMC_reverted(); if (__rev1) { revertedLog = true; } else { revertedLog = false; }

        assert(revertedMin && revertedLog);
    }

    receive() external payable {}
